    kind: SESSIONS[kind] ? kind : 'core',
    title: `${s.title} · poids du corps`,
    objective: s.objective,
    notes: s.notes,
    level: lv,
    levelCount: s.levels.length,
    warmup: WARMUP,
    exercises,
    minutes: strengthMinutes(exercises),
